```java
package lab;

import java.math.RoundingMode;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.kstream.KTable;
import org.apache.kafka.streams.kstream.Produced;

public final class FxTopology {
    public static final String RATES_TOPIC = "fx.rates";
    public static final String PURCHASES_TOPIC = "fx.purchases";
    public static final String OUTPUT_TOPIC = "fx.purchase-usd";

    private FxTopology() {}

    public static Topology buildTopology() {
        StreamsBuilder builder = new StreamsBuilder();
        JsonSerde<Rate> rateSerde = new JsonSerde<>(Rate.class);
        JsonSerde<Purchase> purchaseSerde = new JsonSerde<>(Purchase.class);
        JsonSerde<EnrichedPurchase> enrichedSerde = new JsonSerde<>(EnrichedPurchase.class);

        KTable<String, Rate> rates = builder.table(
                RATES_TOPIC, Consumed.with(Serdes.String(), rateSerde));
        KStream<String, Purchase> purchases = builder.stream(
                PURCHASES_TOPIC, Consumed.with(Serdes.String(), purchaseSerde));

        purchases.join(rates, FxTopology::enrich)
                .to(OUTPUT_TOPIC, Produced.with(Serdes.String(), enrichedSerde));

        return builder.build();
    }

    static EnrichedPurchase enrich(Purchase purchase, Rate rate) {
        return new EnrichedPurchase(
                purchase.purchaseId(),
                purchase.currency(),
                purchase.amount(),
                purchase.amount().multiply(rate.usdPerUnit()).setScale(2, RoundingMode.HALF_UP),
                rate.usdPerUnit(),
                rate.effectiveAt(),
                purchase.purchasedAt());
    }
}
```

